sys_ws_operation.operation_script:
(function process(request, response) {

    try {

        var result = [];

        // ✅ Query params (optional)
        var caseNumber = request.queryParams.number;
        var state = request.queryParams.state;

        var gr = new GlideRecord('x_1558402_smart_0_support_case');

        // ✅ Apply filters
        if (caseNumber) {
            gr.addQuery('number', caseNumber);
        }

        if (state) {
            gr.addQuery('state', state);
        }

        gr.query();

        while (gr.next()) {

            result.push({
                case_number: gr.getValue('number'),
                customer: gr.getDisplayValue('customer'),
                asset: gr.getDisplayValue('asset'),
                priority: gr.getValue('priority'),
                state: gr.getValue('state'),
                description: gr.getValue('description'),

            });
        }

        response.setStatus(200);
        response.setBody({
            count: result.length,
            data: result
        });

    } catch (e) {

        gs.error("Case GET API Error: " + e.message);

        response.setStatus(500);
        response.setBody({
            message: "Error fetching case records"
        });
    }

})(request, response);
